package com.sensei.phonkwalk;

import com.google.inject.Provides;
import java.util.Arrays;
import java.util.List;
import java.util.function.ObjIntConsumer;
import java.util.function.ToIntFunction;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Replaces the local player's walk and idle animations with a selectable
 * matched pair - purely cosmetic and entirely client-side, changing only how
 * your own client draws you. Nothing is sent to the server and no other player
 * sees it.
 * <p>
 * <b>All eight locomotion slots are overridden together, not just the walk.</b>
 * An actor's locomotion is a set of separate animations, and the engine swaps
 * between them constantly - the baseline human ones sit in one contiguous
 * block ({@code HUMAN_WALK_F/B/L/R} and {@code HUMAN_TURNONSPOT}) precisely
 * because they are meant to be used as a set. Overriding only the forward walk
 * leaves the other seven as stock human animations, so the character snaps
 * upright the instant it strafes, backs up, turns, or stops - which is exactly
 * how a style stops looking like a style.
 * <p>
 * Where a style has no animation of its own for a slot, that slot is normally
 * left alone rather than filled with something ill-fitting - a forward walk in
 * a sideways slot shows the character walking forward while moving sideways.
 * Turning on the spot is the exception that always gets filled, holding the
 * style's idle so the character keeps its crouch/slump while the engine
 * rotates the model.
 * <p>
 * A {@link PhonkWalkStyle#usesOneContinuousAnimation()} style overrides that
 * caution entirely and fills every slot with its single animation, because for
 * those the ill-fitting alternative is worse: any stock slot visibly cuts the
 * loop off mid-cycle the moment the player strafes or backs up.
 * <p>
 * Filling the slots is not quite enough on its own, because the engine also
 * caches a RESOLVED pose and re-derives it on its own schedule - after a
 * combat swing, for instance - sometimes landing on the stock animation
 * instead of the override. {@link AnimationSlot#correctPose} catches that
 * narrow case, which is what keeps the style from dropping between attacks.
 * <p>
 * <b>The override follows the run TOGGLE, not actual movement.</b> Those are
 * not the same thing: with run enabled, a move of a single tile is still
 * performed as a walk, since running requires two tiles of movement in a tick.
 * Keying off "is the character walking right now" would therefore fire the
 * override for one step every time the player clicked an adjacent tile in run
 * mode. The toggle is a deliberate, stable choice, so that is what gates this.
 * {@link PhonkWalkConfig#applyWhileRunning()} lifts the gate entirely and also
 * puts the chosen walk in the run slot, for players who want it visible all the
 * time.
 * <p>
 * <b>Why this re-asserts every client tick rather than writing once:</b> these
 * slots are engine-owned. The client recomputes an actor's locomotion
 * animations from their equipment whenever it rebuilds their appearance (a
 * weapon swap being the obvious trigger, though anything that rebuilds the
 * composition does it), silently dropping a one-shot write. Re-checking every
 * tick is the only durable way to hold an override on a field the engine also
 * writes to. See {@link AnimationSlot} for how each slot survives that shared
 * ownership without losing track of the real value underneath.
 */
@Slf4j
@PluginDescriptor(
	name = "Phonk Walk",
	description = "Replace your character's walking and idle animations with a selectable alternative",
	tags = {"cosmetic", "animation", "walk", "walking", "idle", "emote", "visual", "drunk", "fonk", "phonk", "sensei"}
)
public class PhonkWalkPlugin extends Plugin
{
	/** The client's "no animation" sentinel, and this plugin's "nothing captured yet". */
	private static final int NO_ANIMATION = -1;

	/** Value of {@link VarPlayerID#OPTION_RUN} when the player has run mode switched on. */
	private static final int RUN_ENABLED = 1;

	@Inject
	private Client client;

	@Inject
	private PhonkWalkConfig config;

	@Inject
	private ClientThread clientThread;

	private final AnimationSlot walkSlot =
		new AnimationSlot(Player::getWalkAnimation, Player::setWalkAnimation);
	private final AnimationSlot idleSlot =
		new AnimationSlot(Player::getIdlePoseAnimation, Player::setIdlePoseAnimation);
	private final AnimationSlot runSlot =
		new AnimationSlot(Player::getRunAnimation, Player::setRunAnimation);
	// Sideways/backward movement. The engine uses these for small positional
	// adjustments instead of turning the model, so leaving them alone is what
	// made a style pop back to the upright human walk mid-step.
	private final AnimationSlot walkLeftSlot =
		new AnimationSlot(Player::getWalkRotateLeft, Player::setWalkRotateLeft);
	private final AnimationSlot walkRightSlot =
		new AnimationSlot(Player::getWalkRotateRight, Player::setWalkRotateRight);
	private final AnimationSlot walkBackSlot =
		new AnimationSlot(Player::getWalkRotate180, Player::setWalkRotate180);
	// Turning on the spot while stationary.
	private final AnimationSlot turnLeftSlot =
		new AnimationSlot(Player::getIdleRotateLeft, Player::setIdleRotateLeft);
	private final AnimationSlot turnRightSlot =
		new AnimationSlot(Player::getIdleRotateRight, Player::setIdleRotateRight);

	/** Every slot this plugin touches, for the operations that hit all of them. */
	private final List<AnimationSlot> allSlots = Arrays.asList(
		walkSlot, idleSlot, runSlot,
		walkLeftSlot, walkRightSlot, walkBackSlot,
		turnLeftSlot, turnRightSlot);

	/**
	 * Last tick's resolved pose and its frame cursor, used only by {@link
	 * #maintainPoseContinuity} to spot a cursor that was reset out from under
	 * a still-playing animation.
	 */
	private int lastPoseAnimation = NO_ANIMATION;
	private int lastPoseFrame;

	@Provides
	PhonkWalkConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PhonkWalkConfig.class);
	}

	@Override
	protected void shutDown()
	{
		// clientThread.invoke because this touches live Actor state - runs
		// inline when shutDown is already on the client thread, queues
		// correctly if not.
		clientThread.invoke(() ->
		{
			final Player localPlayer = client.getLocalPlayer();
			if (localPlayer != null)
			{
				boolean restored = false;
				for (AnimationSlot slot : allSlots)
				{
					// Accumulated, not short-circuited - every slot must be
					// restored regardless of what the earlier ones did.
					restored |= slot.restore(localPlayer);
				}
				if (restored)
				{
					localPlayer.setPoseAnimation(NO_ANIMATION);
				}
			}
			forgetAll();
		});
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// Drop what was captured WITHOUT restoring it. The Player object
			// it came from is gone, and logging back in produces a fresh one
			// the engine populates itself - holding onto the old values would
			// only risk writing a stale animation onto an unrelated actor.
			forgetAll();
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		final Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null)
		{
			return;
		}

		final PhonkWalkStyle style = config.walkStyle();
		final boolean applyWhileRunning = config.applyWhileRunning();

		// Gated on the run TOGGLE, not on whether the character happens to be
		// walking at this instant. Those differ: with run enabled, a move of a
		// single tile is still performed as a walk, because running needs two
		// tiles of movement in a tick. Keying off actual movement would
		// therefore fire the override for one step every time the player
		// clicked somewhere adjacent while in run mode - which is not what
		// "my walking animation" means to anyone. The toggle is a deliberate,
		// stable choice by the player, so that is what this follows.
		final boolean runEnabled = client.getVarpValue(VarPlayerID.OPTION_RUN) == RUN_ENABLED;
		final boolean active = !runEnabled || applyWhileRunning;

		// The WALK animation deliberately stands in for the run slot rather
		// than some separate run-flavored animation - the point of the option
		// is to keep the chosen walk visible while running, not to introduce a
		// second style.
		final int run = applyWhileRunning ? style.getWalkAnimationId() : NO_ANIMATION;

		// Accumulated with |=, never short-circuited: every slot has to be
		// visited each tick, both to re-assert it and so that a slot the
		// current style declines to override still gets restored.
		boolean changed = false;
		changed |= walkSlot.apply(localPlayer, active ? style.getWalkAnimationId() : NO_ANIMATION);
		changed |= idleSlot.apply(localPlayer, active ? style.getIdleAnimationId() : NO_ANIMATION);
		changed |= runSlot.apply(localPlayer, run);
		changed |= walkLeftSlot.apply(localPlayer, active ? style.getWalkLeftAnimationId() : NO_ANIMATION);
		changed |= walkRightSlot.apply(localPlayer, active ? style.getWalkRightAnimationId() : NO_ANIMATION);
		changed |= walkBackSlot.apply(localPlayer, active ? style.getWalkBackAnimationId() : NO_ANIMATION);
		changed |= turnLeftSlot.apply(localPlayer, active ? style.getTurnOnSpotAnimationId() : NO_ANIMATION);
		changed |= turnRightSlot.apply(localPlayer, active ? style.getTurnOnSpotAnimationId() : NO_ANIMATION);

		if (changed)
		{
			// Clearing the resolved pose forces the engine to re-derive it
			// from the slots just written. Without this a switch would not
			// show until the player next changed between standing and moving,
			// since the pose currently playing was resolved from the OLD
			// values. Only runs on an actual change, never in the steady
			// state, so it cannot cause a per-tick reset.
			localPlayer.setPoseAnimation(NO_ANIMATION);
		}
		else if (localPlayer.getAnimation() == NO_ANIMATION)
		{
			// Nothing changed, but the engine re-resolves the CURRENT pose on
			// its own schedule and can land on the stock animation rather than
			// the override sitting in the slot. The clearest case is combat:
			// finishing an attack swing puts the player back in the weapon's
			// stance, so they visibly straighten up between attacks before
			// dropping back into the style.
			//
			// Only correcting a pose that exactly matches an animation we are
			// replacing - see AnimationSlot#correctPose - keeps this from
			// fighting the engine over poses that are legitimately something
			// else. Gated on no action animation playing, since during a swing
			// the action layer is what is drawn anyway and rewriting the pose
			// underneath it would only risk a pop when the swing ends.
			for (AnimationSlot slot : allSlots)
			{
				if (slot.correctPose(localPlayer))
				{
					break;
				}
			}
		}

		maintainPoseContinuity(localPlayer, style);
	}

	/**
	 * Drops all tracked state without touching the player. The pose tracking
	 * is cleared alongside the slots so a frame cursor remembered from a
	 * previous character or session cannot trigger a bogus continuity
	 * correction on the next one.
	 */
	private void forgetAll()
	{
		allSlots.forEach(AnimationSlot::forget);
		lastPoseAnimation = NO_ANIMATION;
		lastPoseFrame = 0;
	}

	/**
	 * Keeps a style that reuses one animation across slots looking like a
	 * single uninterrupted loop, instead of restarting whenever the player
	 * changes between standing and moving.
	 * <p>
	 * The engine reads the pose from a DIFFERENT slot depending on what the
	 * player is doing, and resets the frame cursor when it switches - which is
	 * correct when the two slots hold different animations, and wrong when
	 * they hold the same one. For {@link PhonkWalkStyle#usesOneContinuousAnimation()}
	 * styles the animation is visibly mid-cycle when that happens, so it jumps
	 * back to the start. Restoring the cursor makes the shamble carry straight
	 * on through the transition.
	 * <p>
	 * The tricky part is telling that reset apart from the loop legitimately
	 * reaching its end and wrapping to zero, which looks identical from one
	 * frame to the next. That is what the {@code getNumFrames} check is for:
	 * only a cursor that was NOT about to wrap can have been reset by
	 * something else.
	 */
	private void maintainPoseContinuity(Player player, PhonkWalkStyle style)
	{
		final int poseAnimation = player.getPoseAnimation();
		int poseFrame = player.getPoseAnimationFrame();

		if (style.usesOneContinuousAnimation()
			&& poseAnimation != NO_ANIMATION
			&& poseAnimation == lastPoseAnimation
			&& poseFrame == 0
			&& lastPoseFrame > 0)
		{
			final Animation animation = client.loadAnimation(poseAnimation);
			if (animation != null && lastPoseFrame + 1 < animation.getNumFrames())
			{
				poseFrame = lastPoseFrame + 1;
				player.setPoseAnimationFrame(poseFrame);
			}
		}

		lastPoseAnimation = poseAnimation;
		lastPoseFrame = poseFrame;
	}

	/**
	 * One engine-owned animation slot held at an overridden value, remembering
	 * the real value underneath so it can be put back.
	 * <p>
	 * The reason this is not simply "save the original once, restore it later"
	 * is that the slot has two writers. The engine rewrites it on every
	 * appearance rebuild, so the real value legitimately changes as the player
	 * re-equips - capturing once at startup would restore whatever they
	 * happened to be holding back then. {@link #apply} therefore tells its OWN
	 * last write apart from a genuine engine write, and only treats the latter
	 * as a new original worth remembering.
	 */
	private static final class AnimationSlot
	{
		private final ToIntFunction<Player> getter;
		private final ObjIntConsumer<Player> setter;

		/** The genuine engine-set value to put back, or {@code NO_ANIMATION} if nothing is overridden. */
		private int original = NO_ANIMATION;

		/** The last value THIS slot wrote, purely to recognize it when reading back. */
		private int applied = NO_ANIMATION;

		AnimationSlot(ToIntFunction<Player> getter, ObjIntConsumer<Player> setter)
		{
			this.getter = getter;
			this.setter = setter;
		}

		/**
		 * @param desired the animation to hold, or {@code NO_ANIMATION} for
		 * "do not override this slot" - in which case anything previously
		 * forced here is put back and the slot is left alone from then on.
		 * @return whether this call actually wrote to the slot.
		 */
		boolean apply(Player player, int desired)
		{
			if (desired == NO_ANIMATION)
			{
				return restore(player);
			}

			final int current = getter.applyAsInt(player);
			if (current == desired)
			{
				// Already ours and unchanged - the overwhelmingly common case,
				// costing one comparison and no write.
				return false;
			}

			// Something other than what we want is here, which is either a
			// genuine engine write (an appearance rebuild reset it) or our own
			// previous value (the user just picked a different style). Only
			// the former is a real animation worth remembering to restore.
			if (current != applied)
			{
				original = current;
			}

			setter.accept(player, desired);
			applied = desired;
			return true;
		}

		/**
		 * If the player's currently-resolved pose is the exact animation this
		 * slot replaces, swap it for the override.
		 * <p>
		 * Narrow on purpose. The resolved pose is engine-owned and changes for
		 * all sorts of legitimate reasons, so this only touches it when it
		 * holds the specific stock animation this slot exists to replace -
		 * which means the engine re-derived the pose and did not pick up the
		 * override. Any other pose is left alone rather than assumed wrong.
		 *
		 * @return whether the pose was actually replaced.
		 */
		boolean correctPose(Player player)
		{
			if (applied == NO_ANIMATION || original == NO_ANIMATION
				|| player.getPoseAnimation() != original)
			{
				return false;
			}
			player.setPoseAnimation(applied);
			// A pose carries its own frame cursor, separate from the animation
			// id and not reset by changing it. Swapping to a shorter animation
			// without resetting leaves the cursor past the end of its frame
			// data, which the renderer indexes out of bounds.
			player.setPoseAnimationFrame(0);
			return true;
		}

		/** @return whether anything was actually put back. */
		boolean restore(Player player)
		{
			if (original == NO_ANIMATION)
			{
				return false;
			}
			setter.accept(player, original);
			forget();
			return true;
		}

		/** Drops tracked state without touching the player - for when the actor is gone. */
		void forget()
		{
			original = NO_ANIMATION;
			applied = NO_ANIMATION;
		}
	}
}

