package com.sensei.phonkwalk;

import net.runelite.api.gameval.AnimationID;

/**
 * The walk animations this plugin can substitute for your character's normal
 * one, each paired with an idle to match. Every entry is an existing in-game
 * animation referenced by its {@link AnimationID} constant - nothing here is
 * new content, it just points the walk and idle slots at animations the client
 * already ships.
 * <p>
 * <b>Pairing an idle with each walk is the point, not a nicety.</b> Overriding
 * only the walk leaves your normal human idle running whenever you stop, which
 * reads as the character bobbing in a way that has nothing to do with how it
 * was just moving.
 * <p>
 * <b>Everything here is PLAYER-rigged.</b> An animation authored for an npc
 * skeleton, applied to the player model, is the single most reliable way to get
 * a broken-looking result - the {@code HUMAN_*} and {@code *_PLAYER_*} families
 * and the player emotes are the safe pools, and this was confirmed the hard
 * way: {@link #ZOMBIE} originally borrowed the npc {@code ZOMBIE_READY} for its
 * idle and looked wrong until it was replaced.
 * <p>
 * A style's animations do not all have to come from one family, and a style may
 * reuse one animation in more than one slot. What matters is that each is
 * player-rigged and suits the slot it fills.
 */
public enum PhonkWalkStyle
{
	/**
	 * The Zombie Walk emote's shamble, used for both moving and standing
	 * still.
	 * <p>
	 * Reusing the walk as the idle is a deliberate exception to the rule that
	 * a walk cycle makes a bad idle. Normally it renders as walking in place,
	 * which is why no other style does this - but shambling on the spot is
	 * what a zombie is supposed to look like, so here the effect is the point
	 * rather than a defect.
	 * <p>
	 * It also sidesteps a real gap: the game ships no player-rigged zombie
	 * idle at all, since every player-rigged zombie animation
	 * ({@code HUMAN_ZOMBIE_WALK}, {@code ZOMBIE_WALK_EMOTE}, its {@code
	 * _LOOP}) is a walk. Earlier attempts borrowed the npc {@code
	 * ZOMBIE_READY} (looked wrong, as npc-rigged animations on a player
	 * usually do) and then the player ghost-transformation idle.
	 * <p>
	 * Being one continuous animation, this fills EVERY locomotion slot - see
	 * {@link #directionalOrContinuous}. Leaving the sideways/backward ones
	 * stock cut the shamble off mid-cycle whenever the player strafed or
	 * backed up.
	 * <p>
	 * If the idle stutters rather than cycling smoothly, {@code
	 * ZOMBIE_WALK_EMOTE_LOOP} is the looping variant of this same emote and
	 * is the first thing to try - an idle slot repeats indefinitely, which is
	 * exactly what that variant is built for.
	 */
	ZOMBIE("Zombie", AnimationID.ZOMBIE_WALK_EMOTE, AnimationID.ZOMBIE_WALK_EMOTE),

	/**
	 * The loose, swaying stagger used when your character is drunk. Walk and
	 * idle are adjacent ids in the same {@code DRUNK_PLAYER_*} block, so they
	 * were authored as a set and should read as one.
	 * <p>
	 * Ships no sideways/backward variants, so strafing keeps the normal human
	 * ones - see the class doc.
	 */
	DRUNK("Drunk", AnimationID.DRUNK_PLAYER_WALK, AnimationID.DRUNK_PLAYER_READY),

	/**
	 * Hunched knuckle-drag from the Ape Atoll greegree transformation. The one
	 * style with a full directional set, so it stays in the crouch when moving
	 * sideways or backwards rather than popping back to an upright human walk.
	 * The family also ships RUN/ATTACK/DEFEND if this is ever extended further.
	 */
	APE("Ape", AnimationID.HUMAN_APE_WALK_F, AnimationID.HUMAN_APE_IDLE,
		AnimationID.HUMAN_APE_WALK_L, AnimationID.HUMAN_APE_WALK_R, AnimationID.HUMAN_APE_WALK_B);

	/** Animation value meaning "leave the player's normal animation in this slot alone". */
	static final int NO_OVERRIDE = -1;

	private final String displayName;
	private final int walkAnimationId;
	private final int idleAnimationId;
	private final int walkLeftAnimationId;
	private final int walkRightAnimationId;
	private final int walkBackAnimationId;

	/** For styles with no sideways/backward variants of their own. */
	PhonkWalkStyle(String displayName, int walkAnimationId, int idleAnimationId)
	{
		this(displayName, walkAnimationId, idleAnimationId, NO_OVERRIDE, NO_OVERRIDE, NO_OVERRIDE);
	}

	PhonkWalkStyle(String displayName, int walkAnimationId, int idleAnimationId,
		int walkLeftAnimationId, int walkRightAnimationId, int walkBackAnimationId)
	{
		this.displayName = displayName;
		this.walkAnimationId = walkAnimationId;
		this.idleAnimationId = idleAnimationId;
		this.walkLeftAnimationId = walkLeftAnimationId;
		this.walkRightAnimationId = walkRightAnimationId;
		this.walkBackAnimationId = walkBackAnimationId;
	}

	int getWalkAnimationId()
	{
		return walkAnimationId;
	}

	/** @return the matching idle, or {@link #NO_OVERRIDE} to keep the normal one. */
	int getIdleAnimationId()
	{
		return idleAnimationId;
	}

	/** @return the sideways-left walk, or {@link #NO_OVERRIDE} if this style has none. */
	int getWalkLeftAnimationId()
	{
		return directionalOrContinuous(walkLeftAnimationId);
	}

	/** @return the sideways-right walk, or {@link #NO_OVERRIDE} if this style has none. */
	int getWalkRightAnimationId()
	{
		return directionalOrContinuous(walkRightAnimationId);
	}

	/** @return the backward walk, or {@link #NO_OVERRIDE} if this style has none. */
	int getWalkBackAnimationId()
	{
		return directionalOrContinuous(walkBackAnimationId);
	}

	/**
	 * Resolves one of the sideways/backward slots.
	 * <p>
	 * A style with its own directional animation always uses it. A style
	 * WITHOUT one normally leaves the slot alone, since the alternative would
	 * be showing a forward walk while the character moves sideways - but that
	 * reasoning does not hold for a {@link #usesOneContinuousAnimation()}
	 * style, where the whole point is that one animation plays unbroken. For
	 * those, leaving these slots stock is what visibly cuts the loop off the
	 * moment the player strafes or backs up, so they get the same animation as
	 * everything else.
	 */
	private int directionalOrContinuous(int declared)
	{
		if (declared != NO_OVERRIDE)
		{
			return declared;
		}
		return usesOneContinuousAnimation() ? walkAnimationId : NO_OVERRIDE;
	}

	/**
	 * @return what to hold while turning on the spot - the style's own idle.
	 * <p>
	 * No style has a dedicated turn-on-spot animation (the human baseline uses
	 * a single {@code HUMAN_TURNONSPOT} for this, and none of these families
	 * ship an equivalent), so holding the idle is what keeps the character in
	 * character through the turn: the engine still rotates the model, it just
	 * stays crouched/slumped/shambling while doing it instead of snapping
	 * upright.
	 * <p>
	 * Deliberately the idle rather than a walk animation, since a walk cycle
	 * played while stationary reads as walking in place. {@link #ZOMBIE} ends
	 * up with a walk here anyway because its idle IS its walk - see its own
	 * note for why that is wanted in that one case.
	 */
	int getTurnOnSpotAnimationId()
	{
		return idleAnimationId;
	}

	/**
	 * @return whether this style uses the SAME animation for standing and
	 * moving, so the two should read as one uninterrupted loop rather than as
	 * a transition between animations.
	 * <p>
	 * Derived rather than declared as its own flag: reusing one animation
	 * across the slots is exactly the condition under which restarting it
	 * looks wrong, so the two can never fall out of step. For a style whose
	 * idle and walk genuinely differ, restarting IS correct - that is a real
	 * change of animation - which is why this is not simply always on.
	 * <p>
	 * Only {@link #ZOMBIE} qualifies today; see {@code
	 * PhonkWalkPlugin#maintainPoseContinuity} for what this enables.
	 */
	boolean usesOneContinuousAnimation()
	{
		return walkAnimationId != NO_OVERRIDE && walkAnimationId == idleAnimationId;
	}

	/** Shown directly in the config dropdown. */
	@Override
	public String toString()
	{
		return displayName;
	}
}

