package com.sensei.phonkwalk;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(PhonkWalkConfig.GROUP)
public interface PhonkWalkConfig extends Config
{
	String GROUP = "phonkwalk";

	@ConfigItem(
		keyName = "walkStyle",
		name = "Walk style",
		description = "Which walk and matching idle to use in place of your normal ones.",
		position = 0
	)
	default PhonkWalkStyle walkStyle()
	{
		return PhonkWalkStyle.ZOMBIE;
	}

	@ConfigItem(
		keyName = "applyWhileRunning",
		name = "Also use while running",
		description = "Off: the style only applies while run is toggled OFF, so a single-tile step taken with run "
			+ "enabled keeps your normal animations.<br>"
			+ "On: the style applies at all times, and the walk animation is used for running too.",
		position = 1
	)
	default boolean applyWhileRunning()
	{
		return false;
	}
}
